impl Document {
    pub(crate) fn compare_mode_in_bsw_instance_ref(
        &self,
        other: &Document,
        a: &ModeInBswInstanceRef,
        b: &ModeInBswInstanceRef,
        path: &str,
    ) -> Result<(), String> {
        self.compare_mode_in_swc_bsw_instance_ref(other, a.base(), b.base(), path)?;
        if a.get_context_bsw_implementation_ref() != b.get_context_bsw_implementation_ref() {
            return Err(format!("{path}: CONTEXT_BSW_IMPLEMENTATION_REF mismatch"));
        }
        if a.get_context_mode_declaration_group_prototype_ref()
            != b.get_context_mode_declaration_group_prototype_ref()
        {
            return Err(format!(
                "{path}: CONTEXT_MODE_DECLARATION_GROUP_PROTOTYPE_REF mismatch"
            ));
        }
        if a.get_target_mode_declaration_ref() != b.get_target_mode_declaration_ref() {
            return Err(format!("{path}: TARGET_MODE_DECLARATION_REF mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_mode_in_swc_bsw_instance_ref(
        &self,
        _other: &Document,
        a: &ModeInSwcBswInstanceRef,
        b: &ModeInSwcBswInstanceRef,
        path: &str,
    ) -> Result<(), String> {
        Self::compare_ar_object(a.base(), b.base(), path)?;
        Ok(())
    }

    pub(crate) fn compare_mode_in_swc_instance_ref(
        &self,
        other: &Document,
        a: &ModeInSwcInstanceRef,
        b: &ModeInSwcInstanceRef,
        path: &str,
    ) -> Result<(), String> {
        self.compare_atp_instance_ref(other, a.base(), b.base(), path)?;
        self.compare_mode_in_swc_bsw_instance_ref(
            other,
            a.mode_in_swc_bsw_instance_ref(),
            b.mode_in_swc_bsw_instance_ref(),
            path,
        )?;
        if a.get_base_ref() != b.get_base_ref() {
            return Err(format!("{path}: BASE_REF mismatch"));
        }
        let list_a = a.get_context_component_refs();
        let list_b = b.get_context_component_refs();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: CONTEXT_COMPONENT_REFS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            if x != y {
                return Err(format!("{path}.CONTEXT_COMPONENT_REFS[{index}] mismatch"));
            }
        }
        if a.get_context_mode_declaration_group_prototype_ref()
            != b.get_context_mode_declaration_group_prototype_ref()
        {
            return Err(format!(
                "{path}: CONTEXT_MODE_DECLARATION_GROUP_PROTOTYPE_REF mismatch"
            ));
        }
        if a.get_context_port_ref() != b.get_context_port_ref() {
            return Err(format!("{path}: CONTEXT_PORT_REF mismatch"));
        }
        if a.get_target_mode_declaration_ref() != b.get_target_mode_declaration_ref() {
            return Err(format!("{path}: TARGET_MODE_DECLARATION_REF mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_timing_condition(
        &self,
        other: &Document,
        a: &TimingCondition,
        b: &TimingCondition,
        path: &str,
    ) -> Result<(), String> {
        self.compare_identifiable(other, a.base(), b.base(), path)?;
        self.compare_variation_point_capable(
            other,
            a.variation_point_capable(),
            b.variation_point_capable(),
            path,
        )?;
        if a.get_timing_condition_formula() != b.get_timing_condition_formula() {
            return Err(format!("{path}: TIMING_CONDITION_FORMULA mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_timing_condition_formula(
        &self,
        other: &Document,
        a: &TimingConditionFormula,
        b: &TimingConditionFormula,
        path: &str,
    ) -> Result<(), String> {
        self.compare_formula_expression(other, a.base(), b.base(), path)?;
        if a.get_timing_argument_ref() != b.get_timing_argument_ref() {
            return Err(format!("{path}: TIMING_ARGUMENT_REF mismatch"));
        }
        if a.get_timing_condition_ref() != b.get_timing_condition_ref() {
            return Err(format!("{path}: TIMING_CONDITION_REF mismatch"));
        }
        if a.get_timing_event_ref() != b.get_timing_event_ref() {
            return Err(format!("{path}: TIMING_EVENT_REF mismatch"));
        }
        if a.get_timing_mode_ref() != b.get_timing_mode_ref() {
            return Err(format!("{path}: TIMING_MODE_REF mismatch"));
        }
        if a.get_timing_variable_ref() != b.get_timing_variable_ref() {
            return Err(format!("{path}: TIMING_VARIABLE_REF mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_timing_extension_resource(
        &self,
        other: &Document,
        a: &TimingExtensionResource,
        b: &TimingExtensionResource,
        path: &str,
    ) -> Result<(), String> {
        self.compare_identifiable(other, a.base(), b.base(), path)?;
        let list_a = a.get_timing_arguments();
        let list_b = b.get_timing_arguments();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: TIMING_ARGUMENTS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self
                .autosar_operation_argument_instances
                .get(*x)
                .ok_or_else(|| {
                    format!("{path}.TIMING_ARGUMENTS[{index}]: id not found in own arena")
                })?;
            let y = other
                .autosar_operation_argument_instances
                .get(*y)
                .ok_or_else(|| {
                    format!("{path}.TIMING_ARGUMENTS[{index}]: id not found in other arena")
                })?;
            self.compare_autosar_operation_argument_instance(
                other,
                x,
                y,
                &format!("{path}.TIMING_ARGUMENTS[{index}]"),
            )?;
        }
        let list_a = a.get_timing_modes();
        let list_b = b.get_timing_modes();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: TIMING_MODES length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self.timing_mode_instances.get(*x).ok_or_else(|| {
                format!("{path}.TIMING_MODES[{index}]: id not found in own arena")
            })?;
            let y = other.timing_mode_instances.get(*y).ok_or_else(|| {
                format!("{path}.TIMING_MODES[{index}]: id not found in other arena")
            })?;
            self.compare_timing_mode_instance(
                other,
                x,
                y,
                &format!("{path}.TIMING_MODES[{index}]"),
            )?;
        }
        let list_a = a.get_timing_variables();
        let list_b = b.get_timing_variables();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: TIMING_VARIABLES length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self.autosar_variable_instances.get(*x).ok_or_else(|| {
                format!("{path}.TIMING_VARIABLES[{index}]: id not found in own arena")
            })?;
            let y = other.autosar_variable_instances.get(*y).ok_or_else(|| {
                format!("{path}.TIMING_VARIABLES[{index}]: id not found in other arena")
            })?;
            self.compare_autosar_variable_instance(
                other,
                x,
                y,
                &format!("{path}.TIMING_VARIABLES[{index}]"),
            )?;
        }
        Ok(())
    }

    pub(crate) fn compare_timing_mode_instance(
        &self,
        other: &Document,
        a: &TimingModeInstance,
        b: &TimingModeInstance,
        path: &str,
    ) -> Result<(), String> {
        self.compare_identifiable(other, a.base(), b.base(), path)?;
        self.compare_variation_point_capable(
            other,
            a.variation_point_capable(),
            b.variation_point_capable(),
            path,
        )?;
        if a.get_mode_instance() != b.get_mode_instance() {
            return Err(format!("{path}: MODE_INSTANCE mismatch"));
        }
        Ok(())
    }
}
